// bundle.js — builds the single upload file from the five source projects.
//
// Usage (run from this folder):
//   node bundle.js
//
// Edit features in projects/modern-interface, projects/dailies-qol, projects/modern-interface-patcher,
// projects/account-drawer, or projects/page-pins-qol. Never edit dist/. Bump the @version in
// projects/_bundle/00-header.js whenever a source project changes.

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const root = __dirname;
const headerFile = path.join(root, 'projects', '_bundle', '00-header.js');
const outFile = path.join(root, 'dist', 'Neopets - Modern QOL.user.js');

const sources = [
  // base skin first: the others expect data-np-modern-interface and the W.__np* APIs.
  ['modern-interface', path.join(root, 'projects', 'modern-interface')],
  // dailies before the patcher so W.__nppDailies exists before the patcher looks for it.
  ['dailies-qol', path.join(root, 'projects', 'dailies-qol')],
  ['modern-interface-patcher', path.join(root, 'projects', 'modern-interface-patcher')],
  ['account-drawer', path.join(root, 'projects', 'account-drawer')],
  ['page-pins-qol', path.join(root, 'projects', 'page-pins-qol')]
];

function fail(msg) {
  console.error('FAILED: ' + msg);
  process.exitCode = 1;
}

function sourceFile(dir) {
  const js = fs.readdirSync(dir).filter(f => f.endsWith('.js'));
  if (js.length !== 1) {
    throw new Error(`${dir} must have exactly one .js file (found: ${js.join(', ') || 'none'})`);
  }
  return path.join(dir, js[0]);
}

function body(file) {
  const src = fs.readFileSync(file, 'utf8');
  const start = src.indexOf('// ==UserScript==');
  const end = src.indexOf('// ==/UserScript==');
  if (start !== 0 || end < 0) {
    throw new Error(`${file} must start with a // ==UserScript== header`);
  }
  return src.slice(end + '// ==/UserScript=='.length).trim();
}

try {
  const header = fs.readFileSync(headerFile, 'utf8').trim();
  if (!header.includes('// ==UserScript==') || !header.includes('// ==/UserScript==')) {
    fail('projects/_bundle/00-header.js must contain a complete userscript header.');
  } else {
    const parts = sources.map(([name, dir]) => {
      const file = sourceFile(dir);
      return `// ---------- ${name} / ${path.basename(file)} ----------\n${body(file)}\n`;
    });

    const output =
      header + '\n\n' +
      '// Bundled by bundle.js. Do not edit this file; edit the source projects and rerun `node bundle.js`.\n\n' +
      parts.join('\n');

    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, output);

    const check = spawnSync(process.execPath, ['--check', outFile], { encoding: 'utf8' });
    if (check.status !== 0) {
      fail(`syntax error in the bundled file.\n${check.stderr}`);
    } else {
      const kb = (Buffer.byteLength(output) / 1024).toFixed(1);
      console.log(`OK  bundled ${sources.length} projects -> ${path.relative(root, outFile)} (${kb} KB)`);
    }
  }
} catch (e) {
  fail(e.message);
}
